 if(tab==='plan')list.innerHTML='<div class="build-kanban">'+statuses.map(([k,l])=>'<section class="build-column" data-build-column="'+k+'"><h4>'+l+' <span>'+items.filter(t=>t.status===k).length+'</span></h4>'+items.map((t,i)=>t.status===k?card(t,i):'').join('')+(items.some(t=>t.status===k)?'':'<p class="build-empty">Aucune tâche.</p>')+'</section>').join('')+'</div>';
 else list.innerHTML=items.length?'<div class="build-rows">'+items.map(card).join('')+'</div>':'<div class="module-empty"><h3>'+({tests:'Aucun scénario pour le moment',experiments:'Votre premier essai commence ici',evidence:'Votre dossier de preuves commence ici'})[tab]+'</h3><p>Ajoutez un élément, puis complétez ses détails dans l’inspecteur.</p></div>';
